(function(){register('Matrix Rain','Classic digital rain with cascading green characters.','retro',
function(c){c._cols=80;c._drops=Array.from({length:80},function(_,i){return{x:i,y:Math.random()*100,speed:.3+Math.random()*.7}})},
function(c,w,h,t){var drops=c._drops,cols=c._cols;c.fillStyle='rgba(0,0,0,.07)';c.fillRect(0,0,w,h);var fw=w/cols,fh=fw*1.4;c.font=Math.floor(fw)+'px monospace';c.textAlign='center';for(var di=0;di<drops.length;di++){var d=drops[di];var len=8+Math.sin(d.x*3+t*.002)*5|0,startY=d.y;for(var i=0;i<len;i++){var cy=startY-i*fh;if(cy<-fh||cy>h+fw)continue;var a=i===0?1:.15+.02*i;c.fillStyle=i===0?'rgba(180,255,180,1)':'rgba(0,200,0,'+a+')';c.fillText(String.fromCharCode(0x30A0+Math.random()*96|0),d.x*fw+fw/2,cy)}d.y+=d.speed;if(d.y>h+fh*10){d.y=-10;d.speed=.3+Math.random()*.7}}}
,'Columns of green characters fall at staggered speeds with varying brightness to simulate depth and a classic digital rain aesthetic.');})();

